// Accessibility Captions renders short-lived, creator-controlled text from normalized events.
// It never retains message bodies and deliberately leaves TTS to Voice Relay.
const MODULE_ID='thsv.accessibility-captions';const MINIMUM_CAPTION_INTERVAL_MS=250;let operation=Promise.resolve();let lastPublishedAt=0;
const manifest = {contractVersion:'2.0.0-preview.1',moduleId:MODULE_ID,name:'Accessibility Captions',version:'4.0.1',minimumCoreVersion:'2.0.0-preview.1',maximumTestedCoreVersion:'2.0.0-preview.1', minimumBridgeVersion: '4.0.1', maximumTestedBridgeVersion: '4.0.1',dependencies:[],requiredCapabilities:[],configurationSchema:'schemas/config.json',eventSubscriptions:['chat.message','channel.follow','channel.subscription','channel.membership','engagement.raid','engagement.super-chat','engagement.donation'],commandsProvided:[],actionsProvided:[],browserSourcesProvided:[],dataStorageOwned:['data/addons/thsv.accessibility-captions/'],installationSteps:['Choose public event types and visual settings.','Add /overlay/addons/thsv.accessibility-captions as a browser source, preview, then enable.'],uninstallationSteps:['No caption text history is retained.'],migrations:[],healthChecks:[{id:'thsv.accessibility-captions.runtime',description:'Confirms ephemeral accessible captions are available.'}]};
function text(value,max=300){return[...(typeof value==='string'?value.replace(/[\u0000-\u001f\u007f]/gu,' ').replace(/\s+/gu,' ').trim():'')].slice(0,max).join('');}
function settingsFor(context){const raw=context.settings||{};return{enabled:raw.enabled===true,showChat:raw.showChat===true,showEvents:raw.showEvents!==false,includeBotMessages:raw.includeBotMessages===true,maximumCharacters:Number.isInteger(raw.maximumCharacters)?Math.min(500,Math.max(40,raw.maximumCharacters)):220,durationSeconds:Number.isInteger(raw.durationSeconds)?Math.min(30,Math.max(3,raw.durationSeconds)):8,fontSize:Number.isInteger(raw.fontSize)?Math.min(72,Math.max(20,raw.fontSize)):36,highContrast:raw.highContrast!==false,backgroundMode:['solid','glass','none'].includes(raw.backgroundMode)?raw.backgroundMode:'solid',backgroundColor:/^#[0-9a-f]{6}$/iu.test(raw.backgroundColor)?raw.backgroundColor:'#000000',textColor:/^#[0-9a-f]{6}$/iu.test(raw.textColor)?raw.textColor:'#ffffff'};}
function eventCaption(event){const name=text(event.user?.displayName||event.user?.name,80)||'Viewer';if(event.eventType==='chat.message')return{name,text:text(event.payload?.message,500)};const labels={'channel.follow':'followed','channel.subscription':'subscribed','channel.membership':'became a member','engagement.raid':'raided the stream','engagement.super-chat':'sent a Super Chat','engagement.donation':'sent a donation'};return{name:'Stream event',text:`${name} ${labels[event.eventType]||'supported the stream'}.`};}
async function process(event,context){const settings=settingsFor(context);if(!settings.enabled||event.metadata?.simulated===true)return;if(event.eventType==='chat.message'&&!settings.showChat)return;if(event.eventType!=='chat.message'&&!settings.showEvents)return;if(event.user?.actorType==='system'||(event.user?.actorType==='bot'&&!settings.includeBotMessages))return;const caption=eventCaption(event);if(!caption.text)return;const now=Date.now();if(now-lastPublishedAt<MINIMUM_CAPTION_INTERVAL_MS)return;lastPublishedAt=now;try{await context.overlay.publish(`${MODULE_ID}.card.show`,{title:caption.name,text:text(caption.text,settings.maximumCharacters),durationMs:settings.durationSeconds*1000,presentationMode:'single',style:{backgroundMode:settings.backgroundMode,backgroundColor:settings.backgroundColor,backgroundOpacity:settings.highContrast?0.96:0.78,accentColor:settings.textColor,textColor:settings.textColor,fontFamily:'broadcast',fontSize:settings.fontSize}},{lane:'independent'});}catch{/* Captions remain ephemeral when the optional overlay is closed. */}}
export default{manifest,required:false,async start(){operation=Promise.resolve();lastPublishedAt=0;},async stop(){await operation.catch(()=>undefined);operation=Promise.resolve();lastPublishedAt=0;},async onEvent(event,context){operation=operation.then(()=>process(event,context),()=>process(event,context));await operation;}};
export{eventCaption};
